class Solution:
    def superPow(self, a, b):
        """
        Calculate a^b mod 1337
        """
        if not b:
            return 1

        # Handle the case where b is a list (like [0])
        if isinstance(b[0], int) and len(b) == 1:
            # Simple case: a^b mod 1337
            result = 1
            a = a % 1337
            for _ in range(b[0]):
                result = (result * a) % 1337
            return result

        # For more complex cases (like b = [2, 3] meaning a^(2^3))
        def pow_mod(base, exp, mod):
            if exp == 0:
                return 1
            if exp % 2 == 0:
                return pow_mod((base * base) % mod, exp // 2, mod)
            else:
                return (base * pow_mod(base, exp - 1, mod)) % mod

        # If b is a list, it represents a^b where b is a power tower
        if isinstance(b[0], int) and len(b) > 1:
            # For b = [x, y, z, ...], it means a^(x^(y^(z^...)))
            # We need to handle this recursively
            if len(b) == 1:
                return pow_mod(a, b[0], 1337)
            else:
                # Calculate the exponent recursively
                exponent = self.superPow(a, b[1:])
                return pow_mod(a, exponent, 1337)

        # Default case for simple exponentiation
        result = 1
        a = a % 1337
        for _ in range(b[0]):
            result = (result * a) % 1337
        return result

